import React, { useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  CircularProgress,
  Grid,
  Paper,
  Tab,
  Tabs,
  Typography,
} from '@mui/material';
import {
  Business as BusinessIcon,
  PrecisionManufacturing as WorkflowIcon,
} from '@mui/icons-material';
import { useLocation, useNavigate } from 'react-router-dom';
import ApiService from '../services/api';
import ManufacturingWorkflowPlanner from './ManufacturingWorkflowPlanner';
import TabSectionNavLinks from './TabSectionNavLinks';

const MSME_PROFILE_TAB_LABELS = ['Profile Details', 'Operations'] as const;

interface MSMEProfileData {
  companyName?: string;
  companyType?: string;
  industry?: string;
  businessDomain?: string;
  cinNumber?: string;
  udyamRegistrationNumber?: string;
  gstNumber?: string;
  panNumber?: string;
  contact?: {
    email?: string;
    phone?: string;
    address?: {
      street?: string;
      city?: string;
      state?: string;
      pincode?: string;
      country?: string;
    };
  };
  business?: {
    annualTurnover?: number;
    numberOfEmployees?: number;
    manufacturingUnits?: number;
    manufacturingWorkflow?: any;
  };
  manufacturingProfile?: {
    msmeType?: string;
    industrySector?: string;
    nicCode?: string;
    yearOfEstablishment?: number;
    locationCity?: string;
    locationState?: string;
    locationCountry?: string;
    numberOfEmployees?: number;
    plantAreaSqft?: number;
    operationalDaysPerYear?: number;
    primaryEnergySource?: string;
    backupEnergySource?: string;
    mainFuelsUsed?: string[];
    waterSource?: string;
    wasteManagementPractice?: string;
    keyProducts?: string[];
    productionCapacityPerMonth?: number;
    productionCapacityUnit?: string;
    supplyChainType?: string;
    logisticsMode?: string;
    certifications?: string[];
    esgMaturityLevel?: string;
    digitalizationLevel?: string;
    carbonAccountingPractice?: string;
    regulatoryExposure?: string[];
    exportActivity?: boolean;
    clusterAssociation?: string;
  };
  operations?: {
    sites?: Array<{
      name?: string;
      city?: string;
      state?: string;
      country?: string;
    }>;
    vehicles?: Array<{
      type?: string;
      fuelType?: string;
      ownership?: string;
    }>;
    subsidiaries?: Array<{
      name?: string;
      controlModel?: string;
    }>;
  };
}

const MSMEProfileSection: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [profile, setProfile] = useState<MSMEProfileData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const activeTab = useMemo(
    () => (location.pathname.endsWith('/workflow-planner') ? 1 : 0),
    [location.pathname]
  );

  useEffect(() => {
    const loadProfile = async () => {
      setLoading(true);
      setError(null);
      try {
        const response = await ApiService.getMSMEProfile();
        setProfile(response?.data || null);
      } catch (err) {
        setProfile(null);
        setError(err instanceof Error ? err.message : 'Unable to load MSME profile.');
      } finally {
        setLoading(false);
      }
    };

    loadProfile();
  }, []);

  const handleTabChange = (_: React.SyntheticEvent, newValue: number) => {
    if (newValue === 0) {
      navigate('/msme-profile');
      return;
    }

    navigate('/msme-profile/workflow-planner');
  };

  const profileAddress = [
    profile?.contact?.address?.street,
    profile?.contact?.address?.city,
    profile?.contact?.address?.state,
    profile?.contact?.address?.pincode,
    profile?.contact?.address?.country,
  ]
    .filter(Boolean)
    .join(', ');

  return (
    <Box>
      <Box sx={{ mb: 3 }}>
        <Typography variant="h4" sx={{ fontWeight: 700, mb: 1 }}>
          MSME Profile
        </Typography>
        <Typography variant="body1" color="text.secondary">
          Manage company information and operations in one place.
        </Typography>
      </Box>

      <Paper sx={{ mb: 3 }}>
        <Tabs value={activeTab} onChange={handleTabChange}>
          <Tab icon={<BusinessIcon />} iconPosition="start" label="Profile Details" />
          <Tab icon={<WorkflowIcon />} iconPosition="start" label="Operations" />
        </Tabs>
        <TabSectionNavLinks
          tabLabels={[...MSME_PROFILE_TAB_LABELS]}
          currentIndex={activeTab}
          onNavigate={(idx) => {
            if (idx === 0) navigate('/msme-profile');
            else navigate('/msme-profile/workflow-planner');
          }}
        />
      </Paper>

      {activeTab === 0 ? (
        <>
          {loading ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', py: 6 }}>
              <CircularProgress />
            </Box>
          ) : error ? (
            <Alert severity="warning" sx={{ mb: 2 }}>
              {error}
            </Alert>
          ) : !profile ? (
            <Alert
              severity="info"
              action={(
                <Button color="inherit" size="small" onClick={() => navigate('/msme-registration')}>
                  Complete registration
                </Button>
              )}
            >
              MSME profile is not available yet.
            </Alert>
          ) : (
            <Grid container spacing={2}>
              <Grid item xs={12}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
                      Company Information
                    </Typography>
                    <Grid container spacing={2}>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Company Name</Typography>
                        <Typography variant="body1">{profile.companyName || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Company Type</Typography>
                        <Typography variant="body1">{profile.companyType || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Industry</Typography>
                        <Typography variant="body1">{profile.industry || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Business Domain</Typography>
                        <Typography variant="body1">{profile.businessDomain || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">CIN Number</Typography>
                        <Typography variant="body1">{profile.cinNumber || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">UDYAM Number</Typography>
                        <Typography variant="body1">{profile.udyamRegistrationNumber || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">GST Number</Typography>
                        <Typography variant="body1">{profile.gstNumber || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">PAN Number</Typography>
                        <Typography variant="body1">{profile.panNumber || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Contact Email</Typography>
                        <Typography variant="body1">{profile.contact?.email || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">NIC Code</Typography>
                        <Typography variant="body1">{profile.manufacturingProfile?.nicCode || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Primary Energy Source</Typography>
                        <Typography variant="body1">{profile.manufacturingProfile?.primaryEnergySource || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Operational Days / Year</Typography>
                        <Typography variant="body1">
                          {profile.manufacturingProfile?.operationalDaysPerYear ?? 'Not provided'}
                        </Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">ESG Maturity</Typography>
                        <Typography variant="body1">{profile.manufacturingProfile?.esgMaturityLevel || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Digitalization Level</Typography>
                        <Typography variant="body1">{profile.manufacturingProfile?.digitalizationLevel || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Export Activity</Typography>
                        <Typography variant="body1">
                          {profile.manufacturingProfile?.exportActivity === undefined
                            ? 'Not provided'
                            : profile.manufacturingProfile?.exportActivity ? 'Yes' : 'No'}
                        </Typography>
                      </Grid>
                    </Grid>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item xs={12}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 1.5 }}>
                      Boundary Definition (Operational Control)
                    </Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                      Define which sites, vehicles, and subsidiaries are included in the greenhouse gas inventory.
                    </Typography>
                    <Grid container spacing={2}>
                      <Grid item xs={12} md={4}>
                        <Paper variant="outlined" sx={{ p: 2, height: '100%' }}>
                          <Typography variant="subtitle2" sx={{ mb: 1 }}>
                            Sites Included
                          </Typography>
                          <Typography variant="body2" color="text.secondary">
                            {profile.operations?.sites?.length
                              ? `${profile.operations.sites.length} site(s) configured`
                              : profile.manufacturingProfile?.locationCity
                                ? `Primary site: ${profile.manufacturingProfile.locationCity}, ${profile.manufacturingProfile.locationState || ''}`.trim()
                                : 'Not configured yet'}
                          </Typography>
                        </Paper>
                      </Grid>
                      <Grid item xs={12} md={4}>
                        <Paper variant="outlined" sx={{ p: 2, height: '100%' }}>
                          <Typography variant="subtitle2" sx={{ mb: 1 }}>
                            Vehicles Included
                          </Typography>
                          <Typography variant="body2" color="text.secondary">
                            {profile.operations?.vehicles?.length
                              ? `${profile.operations.vehicles.length} vehicle asset(s) in boundary`
                              : 'No vehicle inventory configured'}
                          </Typography>
                        </Paper>
                      </Grid>
                      <Grid item xs={12} md={4}>
                        <Paper variant="outlined" sx={{ p: 2, height: '100%' }}>
                          <Typography variant="subtitle2" sx={{ mb: 1 }}>
                            Subsidiaries Included
                          </Typography>
                          <Typography variant="body2" color="text.secondary">
                            {profile.operations?.subsidiaries?.length
                              ? `${profile.operations.subsidiaries.length} subsidiary entity(ies) included`
                              : 'No subsidiaries configured'}
                          </Typography>
                        </Paper>
                      </Grid>
                      <Grid item xs={12}>
                        <Alert severity="info">
                          Use operational control as the default boundary method to establish complete and auditable inventory coverage.
                        </Alert>
                      </Grid>
                    </Grid>
                  </CardContent>
                </Card>
              </Grid>

              <Grid item xs={12}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 1.5 }}>
                      Scope Categorization
                    </Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                      Group all activities into Scope 1 (direct), Scope 2 (indirect purchased energy), and Scope 3 (value chain) so no source is overlooked.
                    </Typography>
                    <Grid container spacing={2}>
                      <Grid item xs={12} md={4}>
                        <Paper variant="outlined" sx={{ p: 2, height: '100%' }}>
                          <Typography variant="subtitle2" sx={{ mb: 1 }}>
                            Scope 1
                          </Typography>
                          <Typography variant="body2" color="text.secondary">
                            Direct emissions from owned fuel combustion, on-site processes, and company-operated vehicles.
                          </Typography>
                        </Paper>
                      </Grid>
                      <Grid item xs={12} md={4}>
                        <Paper variant="outlined" sx={{ p: 2, height: '100%' }}>
                          <Typography variant="subtitle2" sx={{ mb: 1 }}>
                            Scope 2
                          </Typography>
                          <Typography variant="body2" color="text.secondary">
                            Indirect emissions from purchased electricity, steam, heating, and cooling.
                          </Typography>
                        </Paper>
                      </Grid>
                      <Grid item xs={12} md={4}>
                        <Paper variant="outlined" sx={{ p: 2, height: '100%' }}>
                          <Typography variant="subtitle2" sx={{ mb: 1 }}>
                            Scope 3
                          </Typography>
                          <Typography variant="body2" color="text.secondary">
                            Upstream and downstream value-chain emissions including suppliers, logistics, travel, and waste.
                          </Typography>
                        </Paper>
                      </Grid>
                    </Grid>
                  </CardContent>
                </Card>
              </Grid>

              <Grid item xs={12}>
                <Card>
                  <CardContent>
                    <Typography variant="h6" sx={{ fontWeight: 700, mb: 1.5 }}>
                      Company Location and Registration Snapshot
                    </Typography>
                    <Grid container spacing={2}>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Registered Address</Typography>
                        <Typography variant="body1">{profileAddress || 'Not provided'}</Typography>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Typography variant="body2" color="text.secondary">Plant Location</Typography>
                        <Typography variant="body1">
                          {[profile.manufacturingProfile?.locationCity, profile.manufacturingProfile?.locationState, profile.manufacturingProfile?.locationCountry]
                            .filter(Boolean)
                            .join(', ') || 'Not provided'}
                        </Typography>
                      </Grid>
                    </Grid>
                  </CardContent>
                </Card>
              </Grid>
            </Grid>
          )}
        </>
      ) : (
        <ManufacturingWorkflowPlanner />
      )}
    </Box>
  );
};

export default MSMEProfileSection;
