import React, { useMemo } from 'react';
import { Alert, Chip, Stack, Typography } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import { useLocation } from 'react-router-dom';
import { BASELINE_SOFTWARE_VERSION } from '../constants/version';

interface PageInfoConfig {
  title: string;
  /** Context shown under the title for the current route. */
  pageDescription: string;
}

const DEFAULT_INFO: PageInfoConfig = {
  title: 'Sustainow Carbon Intelligence',
  pageDescription:
    'Activity data, documents, and transactions are reconciled with verified emission factors so footprint results stay consistent across modules.',
};

const PAGE_INFO_MAP: Array<{ match: RegExp; config: PageInfoConfig }> = [
  {
    match: /^\/msme-profile(\/workflow-planner)?/,
    config: {
      title: 'Company Profile and Operations Baseline',
      pageDescription:
        'Sector, manufacturing profile, and operational inputs are aligned so downstream carbon models use a granular, consistent baseline.',
    },
  },
  {
    match: /^\/operations/,
    config: {
      title: 'Operations Workflow Planner',
      pageDescription:
        'Process steps are mapped to emission-relevant activities so spend and resource lines roll up into scope-level estimates.',
    },
  },
  {
    match: /^\/dashboard/,
    config: {
      title: 'Operational Control Center',
      pageDescription:
        'Signals blend assessment history, live transaction carbon fields, and data checks so totals reflect the latest reconciled activity picture.',
    },
  },
  {
    match: /^\/carbon-footprint/,
    config: {
      title: 'GHG Emissions Assessment',
      pageDescription:
        'Per-transaction factors (grid, fuels, location, profile) and category passes combine for higher-fidelity kg CO₂e totals.',
    },
  },
  {
    match: /^\/reporting/,
    config: {
      title: 'Compliance and Disclosure Reporting',
      pageDescription:
        'Outputs align BRSR-style disclosures with reconciled assessments and scope splits so reports trace back to the same calculation pipeline.',
    },
  },
  {
    match: /^\/(document-upload|data|document-management)/,
    config: {
      title: 'Evidence and Document Intelligence',
      pageDescription:
        'Bills and line items are parsed into normalized transactions for the shared footprint engine with document-level quality signals.',
    },
  },
  {
    match: /^\/recommendations/,
    config: {
      title: 'Recommendations',
      pageDescription:
        'Reduction opportunities are prioritized using your latest assessment, implemented actions, and sector-specific abatement levers.',
    },
  },
  {
    match: /^\/incentives/,
    config: {
      title: 'Benefits and Incentives',
      pageDescription:
        'Programs are matched to your sector, footprint profile, and eligibility signals from onboarding and assessments.',
    },
  },
  {
    match: /^\/carbon-savings/,
    config: {
      title: 'Carbon Savings',
      pageDescription:
        'Period comparisons and recommendation uptake help attribute avoided emissions to specific initiatives where data allows.',
    },
  },
  {
    match: /^\/(carbon-credits|carbon-trading)/,
    config: {
      title: 'Carbon Credits and Trading',
      pageDescription:
        'Pool balances, retirements, and portfolio snapshots draw on the same reconciled ledger used across the platform.',
    },
  },
  {
    match: /^\/carbon-forecasting/,
    config: {
      title: 'Carbon Forecasting',
      pageDescription:
        'Historical assessments and trends extend into scenario-style drivers informed by your operational and emissions history.',
    },
  },
  {
    match: /^\/gift-schemes|^\/gift-applications/,
    config: {
      title: 'GIFT Schemes and Applications',
      pageDescription:
        'Eligibility rules are checked against your MSME profile and document evidence to streamline application readiness.',
    },
  },
  {
    match: /^\/green-loans/,
    config: {
      title: 'Green Financing',
      pageDescription:
        'Emissions intensity and green project signals feed lender-ready summaries derived from your latest footprint data.',
    },
  },
  {
    match: /^\/ai-email-agent/,
    config: {
      title: 'Email Carbon Import',
      pageDescription:
        'Mailbox transactions are parsed and categorized, then handed off to the same assessment engine used for manual uploads.',
    },
  },
  {
    match: /^\/multi-agent-management|^\/multi-agent-dashboard|^\/optimized-multi-agent-dashboard/,
    config: {
      title: 'System orchestration',
      pageDescription:
        'Define and monitor workflows, parallel task groups, and triggers that fan out granular work across the emissions stack.',
    },
  },
  {
    match: /^\/msme-list/,
    config: {
      title: 'MSME Directory',
      pageDescription:
        'Directory views aggregate profile and footprint status flags for portfolio-level review.',
    },
  },
  {
    match: /^\/data-privacy/,
    config: {
      title: 'Data Privacy',
      pageDescription:
        'Controls govern how personal or commercial identifiers attached to transactions and documents may be processed.',
    },
  },
  {
    match: /^\/settings/,
    config: {
      title: 'Settings',
      pageDescription:
        'Account preferences tune tasks, notifications, and integration defaults across the platform.',
    },
  },
  {
    match: /^\/information/,
    config: {
      title: 'Information',
      pageDescription:
        'Contextual help and in-app guidance reflect the same verified knowledge base used for carbon decisions.',
    },
  },
  {
    match: /^\/manufacturing-workflow/,
    config: {
      title: 'Manufacturing Workflow',
      pageDescription:
        'Equipment and line-level detail align with emission drivers before assessments run.',
    },
  },
];

const hiddenRoutes = new Set([
  '/',
  '/login',
  '/register',
  '/forgot-password',
  '/reset-password',
  '/privacy-policy',
  '/terms-of-service',
  '/help',
  '/admin/login',
]);

interface PageInformationBannerProps {
  compact?: boolean;
}

const PageInformationBanner: React.FC<PageInformationBannerProps> = ({ compact = false }) => {
  const location = useLocation();
  const theme = useTheme();

  const info = useMemo(() => {
    const pathname = location.pathname || '/';
    const matched = PAGE_INFO_MAP.find((entry) => entry.match.test(pathname));
    return matched?.config || DEFAULT_INFO;
  }, [location.pathname]);

  if (hiddenRoutes.has(location.pathname || '')) {
    return null;
  }

  return (
    <Alert
      severity="info"
      variant="outlined"
      sx={{
        mb: compact ? 0 : 1,
        borderColor: 'info.light',
        background:
          theme.palette.mode === 'light'
            ? 'linear-gradient(130deg, rgba(33, 150, 243, 0.08), rgba(76, 175, 80, 0.05))'
            : 'linear-gradient(130deg, rgba(33, 150, 243, 0.18), rgba(76, 175, 80, 0.12))',
        py: compact ? 0.25 : undefined,
      }}
    >
      <Stack direction={{ xs: 'column', md: 'row' }} spacing={1.5} alignItems={{ xs: 'flex-start', md: 'center' }}>
        <Stack spacing={0.5} sx={{ flex: 1 }}>
          <Typography
            variant={compact ? 'body2' : 'subtitle1'}
            sx={{ fontWeight: 700, letterSpacing: 0.1 }}
          >
            {info.title}
          </Typography>
          <Typography
            variant="body2"
            color="text.secondary"
            sx={{ lineHeight: 1.45, maxWidth: { md: '72ch' } }}
          >
            {info.pageDescription}
          </Typography>
        </Stack>
        <Chip
          size="small"
          color="success"
          label={`Software Version ${BASELINE_SOFTWARE_VERSION}`}
          sx={{ fontWeight: 700, flexShrink: 0 }}
        />
      </Stack>
    </Alert>
  );
};

export default PageInformationBanner;
