import axios from 'axios';

const API_BASE_URL = process.env.REACT_APP_API_URL || 'https://carbonintelligence.sustainow.in/api';
export const SUPPORTED_DOCUMENT_MIME_TYPES = new Set([
  'application/pdf',
  'image/jpeg',
  'image/jpg',
  'image/png',
  'image/webp',
  'image/tiff',
  'image/bmp',
  'text/plain',
  'text/csv',
  'application/vnd.ms-excel',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
]);

export const SUPPORTED_DOCUMENT_EXTENSIONS = [
  '.pdf',
  '.jpg',
  '.jpeg',
  '.png',
  '.webp',
  '.tif',
  '.tiff',
  '.bmp',
  '.txt',
  '.csv',
  '.xlsx',
  '.xls',
];

export const SUPPORTED_DOCUMENT_ACCEPT_MAP: Record<string, string[]> = {
  'application/pdf': ['.pdf'],
  'image/jpeg': ['.jpg', '.jpeg'],
  'image/png': ['.png'],
  'image/webp': ['.webp'],
  'image/tiff': ['.tif', '.tiff'],
  'image/bmp': ['.bmp'],
  'text/plain': ['.txt'],
  'text/csv': ['.csv'],
  'application/vnd.ms-excel': ['.xls'],
'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx'],
};

export const SUPPORTED_DOCUMENT_TYPE_LABEL = 'PDF, JPG, JPEG, PNG, WEBP, TIFF, BMP, TXT, CSV,XLSX,XLS';

export interface Document {
  id: string;
  fileName: string;
  originalName: string;
  documentType: string;
  status: 'uploaded' | 'processing' | 'processed' | 'failed' | 'duplicate';
  createdAt: string;
  extractedData?: {
    amount: number;
    vendor: {
      name: string;
      address?: string;
      phone?: string;
      email?: string;
    };
    date: string;
    description: string;
    category: string;
    subcategory?: string;
    items?: Array<{
      name: string;
      quantity: number;
      unit: string;
      price: number;
      total: number;
    }>;
    tax?: {
      cgst: number;
      sgst: number;
      igst: number;
      total: number;
    };
    paymentMethod?: string;
    referenceNumber?: string;
  };
  duplicateDetection?: {
    isDuplicate: boolean;
    duplicateType: string;
    similarityScore: number;
    matchedDocumentId: string;
    duplicateReasons: string[];
  };
  processingResults?: {
    confidence: number;
    processingTime: number;
    errors: string[];
    warnings: string[];
  };
  carbonFootprint?: {
    co2Emissions: number;
    emissionFactor: number;
    calculationMethod: string;
    sustainabilityScore: number;
    emissionBreakdown?: {
      scope1?: number;
      scope2?: number;
      scope3?: number;
    };
  };
  notes?: string;
  tags?: string[];
}

export interface DocumentStatistics {
  totalDocuments: number;
  documentsByType: Record<string, number>;
  documentsByStatus: Record<string, number>;
  totalAmount: number;
  totalCarbonFootprint: number;
  duplicateCount: number;
  averageProcessingTime: number;
  documentsByMonth: Record<string, number>;
}

export interface UploadResponse {
  success: boolean;
  message: string;
  document: Document;
}

export interface DocumentsResponse {
  success: boolean;
  documents: Document[];
  pagination: {
    current: number;
    pages: number;
    total: number;
  };
}

export interface StatisticsResponse {
  success: boolean;
  statistics: DocumentStatistics;
}

/** API may return Mongo `_id`; UI expects string `id`. */
const normalizeDocumentRecord = <T extends Record<string, unknown>>(raw: T): T & { id: string } => {
  const id =
    (typeof raw.id === 'string' && raw.id) ||
    (raw._id != null ? String(raw._id) : '');
  const { _id: _drop, ...rest } = raw as T & { _id?: unknown };
  return { ...rest, id } as T & { id: string };
};

const normalizeDocumentList = (documents: unknown[]): Document[] =>
  (documents || []).map((doc) =>
    normalizeDocumentRecord(doc as Record<string, unknown>),
  ) as unknown as Document[];

class DocumentService {
  private baseURL = API_BASE_URL;

  private getAuthHeaders() {
    const token = localStorage.getItem('token');
    return token ? { Authorization: `Bearer ${token}` } : {};
  }

  /**
   * Upload a document
   */
  async uploadDocument(
    file: File, 
    documentType: string = 'bill', 
    notes?: string
  ): Promise<UploadResponse> {
    
    const formData = new FormData();
    
    formData.append('document', file);
    formData.append('documentType', documentType);
    if (notes) {
      formData.append('notes', notes);
    }
    const token = localStorage.getItem("token");


    const response = await axios.post(`${this.baseURL}/documents/upload`, formData, {
      headers: {
        'Content-Type': 'multipart/form-data',
        Authorization: `Bearer ${token}`,
      },
    });

    const data = response.data as UploadResponse & { document?: Record<string, unknown> };
    if (data?.success && data.document) {
      return {
        ...data,
        document: normalizeDocumentRecord(data.document) as UploadResponse['document'],
      };
    }
    return data;
  }

  /**
   * Get all documents with pagination and filters
   */
  async getDocuments(params: {
    page?: number;
    limit?: number;
    status?: string;
    documentType?: string;
    startDate?: string;
    endDate?: string;
  } = {}): Promise<DocumentsResponse> {
    const response = await axios.get(`${this.baseURL}/documents`, {
      params,
      headers: this.getAuthHeaders(),
    });

    const data = response.data as DocumentsResponse;
    if (data?.success && Array.isArray(data.documents)) {
      return { ...data, documents: normalizeDocumentList(data.documents) };
    }
    return data;
  }

  /**
   * Get a specific document by ID
   */
  async getDocument(id: string): Promise<{ success: boolean; document: Document }> {
    const response = await axios.get(`${this.baseURL}/documents/${id}`, {
      headers: this.getAuthHeaders(),
    });
    const data = response.data as { success: boolean; document: Document & { _id?: string } };
    if (data?.success && data.document) {
      return {
        ...data,
        document: normalizeDocumentRecord(data.document as unknown as Record<string, unknown>) as unknown as Document,
      };
    }
    return data;
  }

  /**
   * Download a document
   */
  async downloadDocument(id: string): Promise<Blob> {
    const response = await axios.get(`${this.baseURL}/documents/${id}/download`, {
      responseType: 'blob',
      headers: this.getAuthHeaders(),
    });

    return response.data;
  }

  /**
   * Update document metadata
   */
  async updateDocument(
    id: string, 
    updates: {
      notes?: string;
      tags?: string[];
      documentType?: string;
    }
  ): Promise<{ success: boolean; document: Document }> {
    const response = await axios.put(`${this.baseURL}/documents/${id}`, updates, {
      headers: this.getAuthHeaders(),
    });
    const data = response.data as { success: boolean; document: Document & { _id?: string } };
    if (data?.success && data.document) {
      return {
        ...data,
        document: normalizeDocumentRecord(data.document as unknown as Record<string, unknown>) as unknown as Document,
      };
    }
    return data;
  }

  /**
   * Delete a document
   */
async deleteDocument(id: string): Promise<{ success: boolean; message: string }> {

  const token = localStorage.getItem("token");

  const response = await axios.delete(
    `${this.baseURL}/documents/${id}`,
    {
      headers: {
        Authorization: `Bearer ${token}`,
      },
    }
  );

  return response.data;
}

  /**
   * Reprocess a document
   */
  async reprocessDocument(id: string): Promise<{ success: boolean; message: string; result?: any }> {
    const response = await axios.post(`${this.baseURL}/documents/${id}/reprocess`, null, {
      headers: this.getAuthHeaders(),
    });
    return response.data;
  }

  /**
   * Get document statistics
   */
  async getStatistics(params: {
    startDate?: string;
    endDate?: string;
  } = {}): Promise<StatisticsResponse> {
    const response = await axios.get(`${this.baseURL}/documents/statistics/overview`, {
      params,
      headers: this.getAuthHeaders(),
    });

    return response.data;
  }

  /**
   * Get duplicate documents
   */
  async getDuplicates(params: {
    page?: number;
    limit?: number;
  } = {}): Promise<DocumentsResponse> {
    const response = await axios.get(`${this.baseURL}/documents/duplicates`, {
      params,
      headers: this.getAuthHeaders(),
    });

    const data = response.data as DocumentsResponse;
    if (data?.success && Array.isArray(data.documents)) {
      return { ...data, documents: normalizeDocumentList(data.documents) };
    }
    return data;
  }

  /**
   * Create a download link for a document
   */
  createDownloadLink(blob: Blob, filename: string): string {
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    window.URL.revokeObjectURL(url);
    return url;
  }

  /**
   * Format file size for display
   */
  formatFileSize(bytes: number): string {
    if (bytes === 0) return '0 Bytes';
    
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  }

  /**
   * Format date for display
   */
  formatDate(dateString: string): string {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  }

  /**
   * Get status color for UI
   */
  getStatusColor(status: string): 'default' | 'primary' | 'secondary' | 'error' | 'info' | 'success' | 'warning' {
    switch (status) {
      case 'processed':
        return 'success';
      case 'failed':
        return 'error';
      case 'duplicate':
        return 'warning';
      case 'processing':
        return 'info';
      default:
        return 'default';
    }
  }

  /**
   * Get document type icon
   */
  getDocumentTypeIcon(documentType: string): string {
    switch (documentType) {
      case 'bill':
        return '📄';
      case 'receipt':
        return '🧾';
      case 'invoice':
        return '📋';
      case 'statement':
        return '📊';
      default:
        return '📄';
    }
  }

  /**
   * Validate file before upload
   */
  validateFile(file: File): { valid: boolean; error?: string } {
    const mimeType = (file.type || '').toLowerCase();
    const fileName = (file.name || '').toLowerCase();
    const isSupportedMimeType = SUPPORTED_DOCUMENT_MIME_TYPES.has(mimeType);
    const hasSupportedExtension = SUPPORTED_DOCUMENT_EXTENSIONS.some((ext) => fileName.endsWith(ext));

    if (!isSupportedMimeType && !hasSupportedExtension) {
      return {
        valid: false,
        error: `Unsupported file type. Allowed types: ${SUPPORTED_DOCUMENT_TYPE_LABEL}`,
      };
    }

    // Check file size (10MB limit)
    const maxSize = 10 * 1024 * 1024; // 10MB
    if (file.size > maxSize) {
      return { valid: false, error: 'File size must be less than 10MB' };
    }

    return { valid: true };
  }
}

export default new DocumentService();