const InformationPage: React.FC = () => {
  const [versionMetadata, setVersionMetadata] = useState<VersionMetadata>({
    baselineCodebaseVersion: BASELINE_SOFTWARE_VERSION,
    apiVersion: BASELINE_SOFTWARE_VERSION,
  });
  const [versionError, setVersionError] = useState<string | null>(null);

  useEffect(() => {
    let isMounted = true;

    const loadVersionMetadata = async () => {
      try {
        const metadata = await ApiService.getVersionMetadata();
        if (isMounted) {
          setVersionMetadata(metadata);
          setVersionError(null);
        }
      } catch (error) {
        if (isMounted) {
          setVersionMetadata({
            baselineCodebaseVersion: BASELINE_SOFTWARE_VERSION,
            apiVersion: BASELINE_SOFTWARE_VERSION,
          });
          setVersionError('Live version metadata is temporarily unavailable.');
        }
      }
    };

    loadVersionMetadata();

    return () => {
      isMounted = false;
    };
  }, []);

  const versionSummary = useMemo(
    () =>
      `UI Baseline: ${versionMetadata.baselineCodebaseVersion} • API: ${versionMetadata.apiVersion}`,
    [versionMetadata]
  );

  return (
    <Box sx={{ pb: 3 }}>
      <Box sx={{ mb: 4 }}>
        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ xs: 'flex-start', sm: 'center' }} sx={{ mb: 1 }}>
          <Box
            component="img"
            src={BRAND_LOGO_SRC}
            alt="Sustainow Carbon Intelligence logo"
            sx={{ width: { xs: 160, sm: 200 }, maxWidth: '100%', height: 'auto', flexShrink: 0 }}
          />
          <Box>
            <Typography
              variant="h3"
              component="h1"
              gutterBottom
              sx={{
                fontWeight: 700,
                mb: 0.5,
                background: 'linear-gradient(135deg, #4caf50 0%, #2e7d32 100%)',
                backgroundClip: 'text',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent',
              }}
            >
              Information
            </Typography>
            <Typography variant="h6" color="text.secondary">
              Software details, user manual, and frequently asked questions.
            </Typography>
          </Box>
        </Stack>
      </Box>

      <Grid container spacing={3}>
        <Grid item xs={12}>
          <Paper
            elevation={0}
            sx={{
              p: { xs: 2.5, md: 3 },
              border: '1px solid rgba(76, 175, 80, 0.2)',
              background:
                'linear-gradient(135deg, rgba(76, 175, 80, 0.06) 0%, rgba(46, 125, 50, 0.08) 100%)',
            }}
          >
            <Stack direction={{ xs: 'column', md: 'row' }} spacing={3} alignItems={{ xs: 'flex-start', md: 'center' }}>
              <Box
                component="img"
                src={BRAND_LOGO_SRC}
                alt="Carbon Intelligence logo"
                sx={{ width: { xs: 220, md: 280 }, maxWidth: '100%', height: 'auto' }}
              />
              <Box>
                <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1.5 }}>
                  <InfoIcon color="primary" />
                  <Typography variant="h5" sx={{ fontWeight: 700 }}>
                    Software Profile
                  </Typography>
                </Stack>
                <Chip
                  icon={<VerifiedIcon />}
                  color="success"
                  label={versionSummary}
                  sx={{ mb: 1.5 }}
                />
                <Typography variant="body2" color="text.secondary">
                  This page provides official software profile details, version traceability, usage guidance, and sustainability reporting context for users, administrators, and compliance stakeholders.
                </Typography>
              </Box>
            </Stack>
            {versionError && (
              <Alert severity="warning" sx={{ mt: 2 }}>
                {versionError}
              </Alert>
            )}
          </Paper>
        </Grid>

        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 3, height: '100%', border: '1px solid rgba(0, 0, 0, 0.08)' }}>
            <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>
              Software Details
            </Typography>
            <List dense>
              {SOFTWARE_DETAILS.map((detail) => (
                <ListItem key={detail.label} alignItems="flex-start" disableGutters sx={{ mb: 1 }}>
                  <ListItemText
                    primary={
                      <Typography variant="subtitle2" color="text.secondary">
                        {detail.label}
                      </Typography>
                    }
                    secondary={<Typography variant="body1">{detail.value}</Typography>}
                  />
                </ListItem>
              ))}
              <ListItem disableGutters alignItems="flex-start">
                <ListItemText
                  primary={
                    <Typography variant="subtitle2" color="text.secondary">
                      Baseline Version
                    </Typography>
                  }
                  secondary={<Typography variant="body1">{versionMetadata.baselineCodebaseVersion}</Typography>}
                />
              </ListItem>
              <ListItem disableGutters alignItems="flex-start">
                <ListItemText
                  primary={
                    <Typography variant="subtitle2" color="text.secondary">
                      API Version
                    </Typography>
                  }
                  secondary={<Typography variant="body1">{versionMetadata.apiVersion}</Typography>}
                />
              </ListItem>
            </List>
          </Paper>
        </Grid>

        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 3, height: '100%', border: '1px solid rgba(0, 0, 0, 0.08)' }}>
            <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 2 }}>
              <ManualIcon color="primary" />
              <Typography variant="h6" sx={{ fontWeight: 700 }}>
                User Manual
              </Typography>
            </Stack>
            <List dense>
              {USER_MANUAL_STEPS.map((step) => (
                <ListItem key={step.title} alignItems="flex-start" disableGutters sx={{ mb: 1 }}>
                  <ListItemText
                    primary={<Typography variant="subtitle1">{step.title}</Typography>}
                    secondary={<Typography variant="body2" color="text.secondary">{step.description}</Typography>}
                  />
                </ListItem>
              ))}
            </List>
          </Paper>
        </Grid>

        <Grid item xs={12}>
          <Paper sx={{ p: 3, border: '1px solid rgba(0, 0, 0, 0.08)' }}>
            <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 2 }}>
              <HelpIcon color="primary" />
              <Typography variant="h6" sx={{ fontWeight: 700 }}>
                Frequently Asked Questions (FAQ)
              </Typography>
            </Stack>
            {FAQ_ITEMS.map((item) => (
              <Accordion key={item.question} disableGutters>
                <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                  <Typography sx={{ fontWeight: 600 }}>{item.question}</Typography>
                </AccordionSummary>
                <AccordionDetails>
                  <Typography color="text.secondary">{item.answer}</Typography>
                </AccordionDetails>
              </Accordion>
            ))}
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default InformationPage;
